// Probe inserted as a runnable script within the revision.
// It records results as plain numbers/strings so the tool can compare structurally.

import * as mathAll from './index.js';

// mathjs default export may vary; normalize.
const math = (mathAll?.create ? mathAll : (mathAll.default && mathAll.default.create ? mathAll.default : mathAll));
const instance = math.create ? math.create() : math;

const sparse = instance.sparse;
const round = instance.round;
const unit = instance.unit;

function toRecord(x) {
  // mathjs numbers may be BigNumber or number; normalize to string for stable comparison.
  // If it's a BigNumber-like with toString, use it.
  if (x && typeof x === 'object' && typeof x.toString === 'function') return x.toString();
  return x;
}

const cases = [
  { expr: 'round(0.145 * 100)', value: round(0.145 * 100) },
  { expr: 'round(evaluate(\'0.145 * 100\'))', value: round(instance.evaluate('0.145 * 100')) },
  { expr: 'round((0.145 * 100), 0)', value: round(0.145 * 100, 0) },
  { expr: 'round(bignumber(0.145 * 100))', value: round(instance.bignumber(0.145 * 100)) },
  { expr: 'round(bignumber(0.145 * 100), bignumber(0))', value: round(instance.bignumber(0.145 * 100), instance.bignumber(0)) },
];

for (const c of cases) {
  probe(c.expr, toRecord(c.value));
}

probe('roundoff_sanity_type_round', typeof round);

