const bignumber = math.bignumber
const __numagentCases = [["round(0.145 * 100)", "round(0.145 * 100)", [], "15"], ["round(evaluate('0.145 * 100'))", "round(evaluate('0.145 * 100'))", [], "15"], ["round((0.145 * 100), 0)", "round((0.145 * 100), 0)", [], "15"], ["round(bignumber(0.145 * 100))", "round(bignumber(0.145 * 100))", [], "bignumber(15)"], ["round(bignumber(0.145 * 100), bignumber(0))", "round(bignumber(0.145 * 100), bignumber(0))", [], "bignumber(15)"]];
for (const [__name, __expr, __binds, __want] of __numagentCases) {
  try {
    for (const __b of __binds) { eval("var " + __b); }
    probe(__name, eval(__expr));
  } catch (e) {
    probe(__name, "__error__: " + ((e && e.name) ? e.name : "Error") + ": " +
          String((e && e.message) ? e.message : e).slice(0, 200));
  }
  if (__want) {
    try { probe("expected::" + __name, eval(__want)); } catch (e) { }
  }
}

